answer:
An 'if' statement placed inside the body of another 'if' or 'else' block is called a nested if statement.
Example:
if (marks >= 35) {
    if (marks >= 75)
        cout << "Distinction";
    else
        cout << "Passed";
} else {
    cout << "Failed";
}

