#include <iostream>
using namespace std;
int main() {
    int num, temp, digit, sum = 0, reverse = 0;
    cout << "Enter an integer: ";
    cin >> num;
    temp = num;
    while (temp > 0) {
        digit = temp % 10;
        sum += digit;
        reverse = reverse * 10 + digit;
        temp /= 10;
    }
    cout << "Given number: " << num << endl;
    cout << "Sum of digits: " << sum << endl;
    cout << "Reversed number: " << reverse << endl;
    return 0;
}

